class Solution {
    public List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        List<Integer> res = new ArrayList<>();
        if (nums == null || n == 0) {
            return res;
        }
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = i; j < n; j++) {
                if (nums[i] > nums[j]) {
                    cnt += 1;
                }
            }
            res.add(cnt);
        }
        return res;
    }
}
